"""Guarded search for coverings of [1, n] by divisibility of differences S - T.

Guard 1: reject S, T that intersect (zero difference gives spurious total coverage).
Guard 2: reject when the divisor mass sum d(|s - t|) is below n (union bound).
Then measure the largest n' such that every k <= n' divides some s - t.
"""
from __future__ import annotations

from math import isqrt
from typing import Dict, List, Sequence, Set


def divisors(m: int) -> List[int]:
    m = abs(m)
    small = [d for d in range(1, isqrt(m) + 1) if m % d == 0]
    return sorted(set(small + [m // d for d in small]))


def guarded_coverage(S: Sequence[int], T: Sequence[int], n: int) -> Dict[str, object]:
    if set(S) & set(T):
        return {"status": "rejected (guard 1: S and T intersect)"}
    diffs = [s - t for s in S for t in T]
    mass = sum(len(divisors(x)) for x in diffs)
    if mass < n:
        return {"status": f"rejected (guard 2: divisor mass {mass} < n = {n})", "mass": mass}
    covered: Set[int] = set()
    for x in diffs:
        covered.update(d for d in divisors(x) if d <= n)
    k = 0
    while k + 1 in covered:
        k += 1
    return {"status": "measured", "mass": mass, "largest_initial_segment": k,
            "fraction_of_[1,n]": len(covered) / n}


if __name__ == "__main__":
    print(guarded_coverage([0, 5], [5, 7], 1000))
    print(guarded_coverage([0, 1], [7], 100))
    primorial = 2 * 3 * 5 * 7 * 11 * 13
    S = [0, 1, 2, 3, 4, 5]
    T = [primorial * j + 7 for j in range(1, 7)]
    print(guarded_coverage(S, T, 60))
